+    }
+
+    // Only use for testing
+    public int runningTasks() {
+        return runningTasks.get();
+    }
+
+    // Only use for testing
+    public int queueSize() {
+        return tasks.size();
+    }
+
+    private void runTask(final T task) {
+        try {
